def collapse_whitespace(s):
    result = []
    prev_was_space = False
    for ch in s:
        if ch in ' \t\n\r\x0b\x0c':
            if not prev_was_space:
                result.append(' ')
                prev_was_space = True
        else:
            result.append(ch)
            prev_was_space = False
    # Strip leading and trailing spaces
    # Convert to string and use strip, then rebuild if needed, but we must strip only the collapsed spaces
    # Since we already have a list, we can strip by finding first and last non-space indices
    # However, the list may contain spaces that were collapsed from runs; we need to strip only those at ends.
    # We'll find the first index where char is not ' '
    start = 0
    while start < len(result) and result[start] == ' ':
        start += 1
    end = len(result) - 1
    while end >= start and result[end] == ' ':
        end -= 1
    return ''.join(result[start:end+1])
